function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*15485863+37);var scores=[];for(var i=0;i<20;i++){scores.push(+(40+R()*60).toFixed(1));}var mean=scores.reduce(function(a,b){return a+b;})/20;var sd=Math.sqrt(scores.reduce(function(a,b){return a+(b-mean)*(b-mean);},0)/20);var pass=scores.filter(function(s){return s>=60;}).length;var top=scores.slice().sort(function(a,b){return b-a;}).slice(0,3);return{tasks:20,pass_rate_pct:+(pass/20*100).toFixed(0),mean_score:+mean.toFixed(1),std_dev:+sd.toFixed(1),top3:top};}
var SEED = 87501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

